package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
}

// searchUsers handles user search with filtering
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Validate auth token
	token := r.Header.Get("X-Auth-Token")
	if token == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	var authCount int
	err := db.QueryRow("SELECT COUNT(*) FROM sessions WHERE token = $1 AND expires_at > NOW()", token).Scan(&authCount)
	if err != nil || authCount == 0 {
		http.Error(w, "Unauthorized", 401)
		return
	}

	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")

	// Build query with parameterized base conditions
	baseQuery := "SELECT id, name, email, role FROM users WHERE active = true"
	var conditions []string
	var args []interface{}
	argIdx := 1

	if name != "" {
		conditions = append(conditions, fmt.Sprintf("name ILIKE $%d", argIdx))
		args = append(args, "%"+name+"%")
		argIdx++
	}

	if dept != "" {
		conditions = append(conditions, fmt.Sprintf("department = $%d", argIdx))
		args = append(args, dept)
		argIdx++
	}

	// Apply additional filter expression if provided
	filterExpr := r.URL.Query().Get("filter")
	if filterExpr != "" {
		// Restrict to known safe column references
		allowedPrefixes := []string{"role=", "created_at>", "created_at<", "status="}
		valid := false
		for _, prefix := range allowedPrefixes {
			if strings.HasPrefix(filterExpr, prefix) {
				valid = true
				break
			}
		}
		if valid {
			// Parse the filter into column and value
			parts := strings.SplitN(filterExpr, "=", 2)
			if len(parts) == 2 {
				col := parts[0]
				val := parts[1]
				// Direct interpolation - developer assumed prefix check is sufficient
				conditions = append(conditions, fmt.Sprintf("%s = '%s'", col, val))
			}
		}
	}

	finalQuery := baseQuery
	if len(conditions) > 0 {
		finalQuery += " AND " + strings.Join(conditions, " AND ")
	}

	rows, err := db.Query(finalQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
